<?php
declare(strict_types=1);require_once __DIR__.'/../includes/bootstrap.php';admin_required();$connection=db();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=filter_input(INPUT_POST,'id',FILTER_VALIDATE_INT);$status=$_POST['status']??'';if($id&&in_array($status,['new','scheduled','in_progress','completed','cancelled'],true)){$statement=$connection->prepare('UPDATE installation_requests SET request_status=? WHERE id=?');$statement->bind_param('si',$status,$id);$statement->execute();flash('success','Installation status updated.');}header('Location: installations.php');exit;}$requests=$connection->query('SELECT i.*,c.full_name,c.phone FROM installation_requests i JOIN customers c ON c.id=i.customer_id ORDER BY i.created_at DESC')->fetch_all(MYSQLI_ASSOC);$success=flash('success');
?><!doctype html><html><head><meta charset="utf-8"><title>Installations | Sammy Tech</title><link rel="stylesheet" href="../assets/css/admin.css"></head><body><div class="admin-layout"><aside><a class="admin-brand" href="index.php"><span>ST</span> SAMMY TECH</a><a href="index.php">Overview</a><a href="catalog.php">Catalog</a><a href="reports.php">Reports</a><a class="side-active" href="installations.php">Installations</a></aside><main class="admin-main"><header><div><p class="eyebrow">Field operations</p><h1>Installation requests.</h1></div></header><?php if($success):?><p class="notice success"><?=e($success)?></p><?php endif;?><section class="panel"><table><thead><tr><th>Customer</th><th>Service</th><th>Location</th><th>Date</th><th>Status</th></tr></thead><tbody><?php foreach($requests as $request):?><tr><td><b><?=e($request['full_name'])?></b><small><?=e($request['phone'])?></small></td><td><?=e($request['service_type'])?></td><td><?=e($request['location'])?></td><td><?=e($request['preferred_date']?:'Not set')?></td><td><form class="status-form" method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=e((string)$request['id'])?>"><select name="status"><?php foreach(['new','scheduled','in_progress','completed','cancelled'] as $status):?><option value="<?=$status?>" <?=$status===$request['request_status']?'selected':''?>><?=ucfirst(str_replace('_',' ',$status))?></option><?php endforeach;?></select><button>Save</button></form></td></tr><?php endforeach;?></tbody></table></section></main></div></body></html>
